BEGIN;

-- G6a stores a preparation-only company packet in the existing task/queue.
-- No row is deleted/reseeded. Existing application contracts remain mandatory.
ALTER TABLE agent_executions ALTER COLUMN application_id DROP NOT NULL;
ALTER TABLE agent_executions ADD CONSTRAINT company_information_application_scope CHECK (COALESCE(
  (application_id IS NOT NULL AND metadata->'executionContract'->>'executionClass' IS DISTINCT FROM 'roost-company-information-v1') OR
  (application_id IS NULL AND metadata->'executionContract'->>'executionClass' = 'roost-company-information-v1'
    AND base_branch IS NULL AND metadata->'readyContextPin'->>'preparationOnly' = 'true' AND metadata->'readyContextPin'->>'modelExecutionQualified' = 'false')
,false));

