CREATE FUNCTION company_information_preparation_valid(t UUID, w UUID, pin JSONB) RETURNS BOOLEAN LANGUAGE plpgsql STABLE AS $$
DECLARE c JSONB:=pin->'contract'; selected_source JSONB; record company_records; task tasks;
BEGIN
 IF pin->>'status' IS DISTINCT FROM 'ready' OR pin->>'preparationOnly' IS DISTINCT FROM 'true'
   OR pin->>'modelExecutionQualified' IS DISTINCT FROM 'false' OR pin->'applicationId' IS DISTINCT FROM 'null'::jsonb
   OR pin->'baseBranch' IS DISTINCT FROM 'null'::jsonb OR pin->>'requestedByType' IS DISTINCT FROM 'user'
   OR pin->'validation'->>'validator' IS DISTINCT FROM 'company-information-packet-v1'
   OR pin->'validation'->>'revision' IS DISTINCT FROM pin->>'revision'
   OR COALESCE(pin->>'revision','') !~ '^[a-f0-9]{64}$'
   OR task_risk_contract_shape(c,company_information_contract_schema()) IS NOT TRUE THEN RETURN false; END IF;
 SELECT * INTO task FROM tasks WHERE id=t AND workspace_id=w;
 IF NOT FOUND OR task.status::text NOT IN ('todo','in_progress')
   OR c->'objective'->>'goalId' IS DISTINCT FROM task.goal_id::text
   OR c->'assignment'->>'agentId' IS DISTINCT FROM task.assigned_workforce_entity_id::text
   OR c->'singleTask'->>'contractId' IS DISTINCT FROM 'roost-task:'||t::text
   OR c->'singleTask'->'problems'->0->>'outcome' IS DISTINCT FROM c->'objective'->>'outcome'
   OR c->'taskRoles'->'accountableManager' IS DISTINCT FROM c->'singleTask'->'accountableManager'
   OR task_interview_pending(t) THEN RETURN false; END IF;
 IF (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(c->'context'->'company')) <> jsonb_array_length(c->'context'->'company') THEN RETURN false; END IF;
 FOR selected_source IN SELECT value FROM jsonb_array_elements(c->'context'->'company') LOOP
   SELECT * INTO record FROM company_records WHERE id::text=selected_source->>'id' AND workspace_id=w AND application_id IS NULL AND status IN ('active','approved','accepted');
   IF NOT FOUND OR to_char(record.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') IS DISTINCT FROM selected_source->>'revision'
     OR COALESCE(NULLIF(trim(record.description),''),NULLIF(trim(record.business_purpose),''),NULLIF(trim(record.desired_state),''),NULLIF(trim(record.expected_behavior),'')) IS NULL THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $$;

-- Preserve each current application guard verbatim after a narrowly matched
-- preparation branch. This forward migration checks its insertion point and
-- leaves role provenance, submission receipts, source watches and interviews
-- active. It cannot admit a running/completed informational execution.
DO $migration$
DECLARE name TEXT; definition TEXT; branch TEXT;
BEGIN
 FOREACH name IN ARRAY ARRAY['task_require_single_scope','task_risk_admission_guard','task_admission_guard','procedure_composition_guard'] LOOP
   SELECT pg_get_functiondef((name||'()')::regprocedure) INTO definition;
   IF position('BEGIN' IN definition)=0 THEN RAISE EXCEPTION 'company_preparation_guard_anchor_missing'; END IF;
   branch:=E'\n -- company-information G6a preparation boundary\n'
     || E' IF TG_TABLE_NAME=''tasks'' THEN\n'
     || E'  IF NEW.execution_readiness->''contract''->>''executionClass''=''roost-company-information-v1'' AND NEW.execution_readiness->>''status''=''ready'' THEN\n'
     || E'   IF company_information_preparation_valid(NEW.id,NEW.workspace_id,NEW.execution_readiness) IS NOT TRUE THEN RAISE EXCEPTION ''company_information_preparation_invalid''; END IF;\n'
     || E'   RETURN NEW;\n  END IF;\n'
     || E' ELSIF TG_TABLE_NAME=''agent_executions'' THEN\n'
     || E'  IF NEW.metadata->''executionContract''->>''executionClass''=''roost-company-information-v1'' THEN\n'
     || E'   IF NEW.application_id IS NOT NULL OR NEW.base_branch IS NOT NULL OR NEW.agent_host_id IS NOT NULL OR NEW.lease_token IS NOT NULL OR NEW.lease_expires_at IS NOT NULL OR NEW.started_at IS NOT NULL OR NEW.attempt<>0 OR NEW.status::text NOT IN (''queued'',''failed'',''cancelled'') OR NEW.metadata->''readyContextPin''->>''preparationOnly'' IS DISTINCT FROM ''true'' OR NEW.metadata->''readyContextPin''->>''modelExecutionQualified'' IS DISTINCT FROM ''false'' THEN RAISE EXCEPTION ''company_information_execution_unqualified''; END IF;\n'
     || E'   IF NEW.status::text=''queued'' AND NOT EXISTS(SELECT 1 FROM tasks x WHERE x.id=NEW.task_id AND x.workspace_id=NEW.workspace_id AND company_information_preparation_valid(x.id,x.workspace_id,x.execution_readiness) AND x.execution_readiness->''contract''=NEW.metadata->''executionContract'' AND x.execution_readiness->>''pinId''=NEW.metadata->''readyContextPin''->>''pinId'' AND x.execution_readiness->>''revision''=NEW.metadata->''readyContextPin''->>''revision'') THEN RAISE EXCEPTION ''company_information_preparation_invalid''; END IF;\n'
     || E'   RETURN NEW;\n  END IF;\n END IF;\n -- end company-information G6a preparation boundary\n';
   EXECUTE overlay(definition placing 'BEGIN'||branch from position('BEGIN' IN definition) for length('BEGIN'));
 END LOOP;
END $migration$;

COMMIT;
